    path: '/api/afaccess/decide',
    handler: async (req, res) => {
      if (req.method !== 'POST') return json(res, 405, { ok: false, reason: 'method' })
      // A5：CSRF 防护——要求同源面板携带的自定义请求头；若有 Origin/Referer 则必须是回环地址
