      if (rec.decision !== null) return json(res, 200, { ok: false, reason: 'already-decided' })
      const decision = args.decision === 'approved' ? 'approved' : 'denied'
      // A5/A6：记忆写入强制绑定服务端 rec.commandHash（忽略客户端提供的任意键）；
