    let qr
    while ((qr = quotedRelRe.exec(scrubbed)) !== null) {
      pushRelative(qr[2].replace(/^['"]+|['"]+$/g, ''))
      scrubbed = scrubbed.slice(0, qr.index) + ' '.repeat(qr[0].length) + scrubbed.slice(qr.index + qr[0].length)
