import { readFile, writeFile, mkdir, rename } from "node:fs/promises";
import { homedir } from "node:os";
import { join, dirname } from "node:path";

// connection:exact 路由优先于 /api prefix 的信任栅栏,必须自己过栅栏(见 handler)
