  if (total === undefined && granted !== undefined && used !== undefined) {
    total = Number(granted) - Number(used);
  }
  if (total === undefined) total = granted;
  const item = {
    currency: "USD",
    total,
    granted,
    used,
    label: "OpenAI 额度",
