    if (store.version < 12) {
      const legacySessions = legacyTrackedSessions();
      try {
        fs.copyFileSync(usageFile(), `${usageFile()}.v${store.version || 1}.bak`);
      } catch (error) {
        // 备份失败不阻塞重建。
