  if (rawProvider === "opencode-go") {
    groupKey = "go|";
  } else if (rawProvider) {
    groupKey = "api|";
  } else if (model === "ox-alpha-free") {
    groupKey = "go|"; // 仅在 OpenCode Go 目录中提供
  } else {
    groupKey = "api|";
